      '<div class="loled-val">'+sc+' / 100</div>'+
    '</div>'+
    '<div class="loled-row">'+
      '<div class="loled-lbl">'+(TH?'ระดับ':'Level')+'</div>'+
      '<div class="loled-pips">'+pips+'</div>'+
      '<div class="loled-lvlval">Lv.'+lv+' — '+esc(lvlLabel(lv))+'</div>'+
    '</div>'+
    (statusHtml||noteHtml?'<div class="loled-divider"></div>':'')+
    statusHtml+
    noteHtml;
})();
